import React from 'react'
import { connect } from 'react-redux'
import { Collapse, Row, Col, Card, Form, Alert, Table, Icon } from 'antd'
import feedbackActions from '../../redux/feedback/actions'
import { FeedbackFormStyle } from './feedbackForm.style'
import EditFeedbackModal from './editFeedbackModal'
import { sortByKey } from '../../../helpers/utility'
import PermissionChecker from '../../../components/permissionChecker'

const { Panel } = Collapse
const { getFeedbackForm, resetStateFeedback } = feedbackActions

class FeedbackForm extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      loading: false,
      modalData: {},
      showEditFeedbackModal: false,
      permissions: []
    }
  }

  componentWillReceiveProps (nextProps) {
    this.setState({
      loading: false,
      permissions: localStorage.getItem('permissions')
    })
  }

  componentDidMount = () => {
    this.props.resetStateFeedback()
    this.props.getFeedbackForm()
  };

  showEditFeedbackModal = (modalData) => {
    this.setState({
      showEditFeedbackModal: true,
      modalData: modalData
    })
  }

  closeEditFeedbackModal = () => {
    this.setState({ showEditFeedbackModal: false })
  }

  renderSettleTable = (tableData) => {
    const { getFeedbackLoading, permissions } = this.props

    let sortedTableData = sortByKey(tableData, 'rating_group')
    const columns = [
      {
        key: 'rating_group',
        title: (
          <div style={{
            display: 'flex',
            paddingTop: '2px' }}>
            <span>
              Rating Group
            </span>
          </div>
        ),
        dataIndex: 'rating_group'
      }, {
        key: 'question',
        title: (
          <div style={{
            display: 'flex',
            paddingTop: '2px' }}>
            <span>
              Feedback Question
            </span>
          </div>
        ),
        dataIndex: 'question'
      }, {
        key: 'comment',
        title: (
          <div style={{
            display: 'flex',
            paddingTop: '2px' }}>
            <span>
              Comment Label
            </span>
          </div>
        ),
        dataIndex: 'comment'
      }, {
        key: 'options',
        title: (
          <div style={{
            display: 'flex',
            paddingTop: '2px' }}>
            <span>
              Multiple Option
            </span>
          </div>
        ),
        render: (val) => {
          return (
            <div>
              { Array.isArray(val)
                ? val.map(option => {
                  return option.label
                }).join(', ') : ''
              }
            </div>
          )
        },
        dataIndex: 'options'
      }, {
        key: 'action',
        title: (
          <div style={{
            display: 'flex',
            paddingTop: '2px' }}>
            <span>
              Action
            </span>
          </div>
        ),
        render: (val, record) => <PermissionChecker permissionSetter={'ops.edit_feedback_form'} permissionGetter={permissions}><Icon type='edit' onClick={() => this.showEditFeedbackModal(record)} style={{ cursor: 'pointer' }} /></PermissionChecker>,
        dataIndex: 'id'
      }
    ]
    return (
      <Table
        columns={columns}
        rowKey={(_, index) => index}
        dataSource={sortedTableData}
        loading={getFeedbackLoading}
        scroll={{ x: true }}
        pagination={false}
        bordered
      />
    )
  };

  render () {
    const {
      showEditFeedbackModal,
      modalData
    } = this.state
    const { feedbackFormData, permissions } = this.props
    return (
      <FeedbackFormStyle>
        <Card>
          {false && (
            <Alert message={'searchMessage'} type='error' />
          )}
          {modalData.form_id &&
          <EditFeedbackModal
            isOpen={showEditFeedbackModal}
            comment={modalData.comment}
            question={modalData.question}
            formId={modalData.form_id}
            options={modalData.options}
            onClosePopupForm={this.closeEditFeedbackModal}
            userid={this.props.match.params.user_id}
            userProfile={123}
          />
          }
          <Row type='flex' justify='center'>
            <Col sm={24} style={{ padding: '20px' }}>
              <h2 style={{ marginBottom: '20px' }}
              >
                Manage Form
              </h2>
              <Collapse
                expandIconPosition={'right'}
                bordered={false}
              >

                <Panel className='feedback-panel' header='Feedback Form for Claim Settled' key='1'>
                  <PermissionChecker permissionSetter={'ops.view_feedback_form'} permissionGetter={permissions}>
                    {this.renderSettleTable(feedbackFormData.settle_data)}
                  </PermissionChecker>
                </Panel>
                <Panel className='feedback-panel' header='Feedback Form for Claim Rejected' key='2'>
                  <PermissionChecker permissionSetter={'ops.view_feedback_form'} permissionGetter={permissions}>
                    {this.renderSettleTable(feedbackFormData.reject_data)}

                  </PermissionChecker>
                </Panel>
              </Collapse>
            </Col>
          </Row>
        </Card>
      </FeedbackFormStyle>
    )
  }
}

const WrappedForm = Form.create({})(FeedbackForm)

export default connect(
  state => ({
    feedbackFormData: state.Feedback.feedbackFormData,
    getFeedbackLoading: state.Loading.GET_FEEDBACK_FORM,
    getFeedbackError: state.Error.GET_FEEDBACK_FORM,
    feedbackFormMessage: state.Feedback.feedbackFormMessage
  }),
  { getFeedbackForm, resetStateFeedback }
)(WrappedForm)
