import React from 'react'
import { connect } from 'react-redux'
import { Form, Row, Col, Input, Button, Modal, notification, message } from 'antd'
import PropTypes from 'prop-types'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import feedbackAction from '../../redux/feedback/actions'
import FailedFetchAlert from '../../../components/failedFetchDataAlert'
import { map, assign, filter } from 'lodash'

const FormItem = Form.Item

const { resetStateFeedback, postEditFeedbackForm } = feedbackAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class EditFeedbackModal extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      providerListData: [],
      radioValue: '',
      options: Object.assign([], props.options),
      resetOptions: Object.assign([], props.options),
      changeOptions: false
    }
  }

  componentDidMount () {
    this.resetState()
  }

  componentWillReceiveProps (nextProps) {
    const { options, isOpen } = nextProps
    const { changeOptions } = this.state

    if (!changeOptions && isOpen) {
      this.setState({ options: Object.assign([], nextProps.options), changeOptions: !changeOptions, resetOptions: Object.assign([], nextProps.options) })
    }
    if (nextProps.postFeedbackFormMessage === 'Successfully edited' &&
        !nextProps.patchEditFeedbackError &&
        !nextProps.patchEditFeedbackLoading) {
      this.successEdit()
    }

    if (!isOpen) {
      this.setState({ changeOptions: !changeOptions, resetOptions: options })
    }
  }

  successEdit = () => {
    notification['success']({
      message: this.props.postFeedbackFormMessage,
      description: ''
    })
    this.handleCancel()
  }

  resetState = () => {
    const { changeOptions, resetOptions } = this.state
    // In case of onClick of Submit the value of options need not be change
    if (this.props.patchEditFeedbackLoading === undefined) {
      this.setState({
        changeOptions: !changeOptions,
        options: resetOptions
      })
    }

    this.props.resetStateFeedback(['postFeedbackFormMessage'])
    this.props.resetLoadingRedux(['POST_EDIT_FEEDBACK_FORM'])
    this.props.resetErrorRedux(['POST_EDIT_FEEDBACK_FORM'])
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const {
      form,
      formId
    } = this.props

    const formValues = form.getFieldsValue()
    const options = this.state.options

    const multipleOptions = map(options, object => assign({ 'label': object.label }))

    let payload = {
      comment: formValues.comment,
      question: formValues.question,
      options: multipleOptions,
      id: formId
    }

    this.props.postEditFeedbackForm(payload)
  }

  handleCancel = () => {
    this.props.form.resetFields()
    this.props.onClosePopupForm()
    this.resetState()
  }

  onChange = e => {
    this.setState({
      radioValue: e.target.value
    })
  };

  handleOptions = value => {
    const { options } = this.state
    let newOption = filter(options, val => { return val.label !== value })
    if (newOption.length < 1) {
      message.error('Atleast one option required')
      return
    }
    this.setState({ options: newOption })
  }

  addOptions = () => {
    let { options } = this.state
    options.push({ 'label': '' })
    this.setState({ options: options })
  }

  onChangeInput = (e, index) => {
    let { options } = this.state
    options[index].label = e.target.value
    this.setState({ options: options })
  }

  render () {
    const { getFieldDecorator } = this.props.form
    const {
      comment,
      question,
      patchEditFeedbackLoading,
      patchEditFeedbackError,
      postFeedbackFormMessage
    } = this.props
    const { options } = this.state
    return (
      <Modal
        title='Edit Customer Personal Info'
        visible={this.props.isOpen}
        onCancel={this.handleCancel}
        footer={null}
        closable
        maskClosable={false} >
        <FailedFetchAlert
          status={'error'}
          isNeedDisplay={patchEditFeedbackError}
          message={postFeedbackFormMessage}
        />
        <Form id='event-form' onSubmit={this.onSubmit} style={{ marginTop: '10px' }}>
          <Row>
            <Col sm={6}>
              Question
            </Col>
            <Col sm={18}>
              <FormItem>
                {getFieldDecorator('question', {
                  initialValue: question,
                  rules: [{ required: true, message: 'Please input a question' }]
                })(<Input />)}
              </FormItem>
            </Col>
          </Row>
          <Row>
            <Col sm={6}>
              Comment label
            </Col>
            <Col sm={18}>
              <FormItem>
                {getFieldDecorator('comment', {
                  initialValue: comment,
                  rules: [{ required: true, message: 'Please input a Label for Comment' }]
                })(<Input />)}
              </FormItem>
            </Col>
          </Row>
          <Row>
            <Col sm={6}>
              Multiple Options
            </Col>
            <Col sm={18}>
              {options !== '' && options.map((value, index) => {
                return (
                  <Row style={{ margin: '3px' }}>
                    <Col sm={18} style={{ margin: '3px' }}>

                      <Input value={value.label} onChange={(e) => this.onChangeInput(e, index)} />

                    </Col>
                    <Col sm={2} style={{ margin: '3px' }}>
                      <Button onClick={() => this.handleOptions(value.label)} icon='delete' />
                    </Col >
                    <Col sm={2} style={{ margin: '3px' }}>
                      <Button onClick={() => this.addOptions()} icon='plus' />
                    </Col >
                  </Row>
                )
              })}
            </Col>
          </Row>
          <FormItem>
            <div style={{ textAlign: 'right' }}>
              <Button
                className='button'
                key='cancel'
                style={{ marginTop: '20px', marginRight: '20px' }}
                onClick={this.handleCancel}
              >
                Cancel
              </Button>
              <Button
                form='event-form'
                className='button'
                key='submit'
                type='primary'
                htmlType='submit'
                style={{ marginTop: '20px' }}
                loading={patchEditFeedbackLoading}
              >
                Submit
              </Button>
            </div>
          </FormItem>
        </Form>
      </Modal>
    )
  }
}

const WrappedEditFeedbackModal = Form.create()(EditFeedbackModal)

WrappedEditFeedbackModal.propTypes = {
  isOpen: PropTypes.bool,
  comment: PropTypes.string,
  question: PropTypes.string,
  formId: PropTypes.number.isRequired,
  options: PropTypes.arrayOf(PropTypes.shape({
    name: PropTypes.string,
    label: PropTypes.string,
    is_selected: PropTypes.bool
  }))
}

WrappedEditFeedbackModal.defaultProps = {
  isOpen: false,
  comment: '',
  question: '',
  options: [{
    name: '',
    label: '',
    is_selected: false
  }]
}

export default connect(
  state => ({
    patchEditFeedbackLoading: state.Loading.POST_EDIT_FEEDBACK_FORM,
    patchEditFeedbackError: state.Error.POST_EDIT_FEEDBACK_FORM,
    postFeedbackFormMessage: state.Feedback.postFeedbackFormMessage
  }),
  {
    resetStateFeedback,
    postEditFeedbackForm,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedEditFeedbackModal)
